<script setup>
import { reactive, onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import { Connection, Refresh, Setting } from '@element-plus/icons-vue'
import PageShell from '../components/PageShell.vue'
import { CULTURE_OPTIONS, WATER_QUALITY_METRICS } from '../config/waterQualityConfig'
import { useMonitorStore } from '../stores/monitor'

const store = useMonitorStore()
const clone = (value) => JSON.parse(JSON.stringify(value))
const form = reactive(clone(store.settings))
const cultureForm = reactive(clone(store.culture))
const metric = (key) => WATER_QUALITY_METRICS.find((item) => item.key === key)
function save() { store.saveSettings(form); store.saveCulture(cultureForm); ElMessage.success('设置已保存，预警与自动控制规则已同步') }
function reset() { store.resetSettings(); Object.assign(form, clone(store.settings)); ElMessage.success('已恢复默认阈值') }
onMounted(() => store.init())
</script>

<template>
  <PageShell title="系统设置"><section class="settings-head"><div><span class="section-kicker">SYSTEM CONFIGURATION</span><p>调整水质安全范围和自动控制规则，设置会立即同步到预警与设备控制。</p></div><div class="settings-actions"><button class="secondary-button" @click="reset"><el-icon><Refresh /></el-icon>恢复默认</button><button class="primary-button" @click="save"><el-icon><Setting /></el-icon>保存设置</button></div></section><section class="settings-layout"><div class="settings-main"><section class="panel settings-panel"><div class="panel-heading"><div><span class="section-kicker">WATER QUALITY THRESHOLDS</span><h2>水质阈值配置</h2></div><span class="simulation-label">当前为本地配置</span></div><div class="threshold-grid"><div class="threshold-row"><div class="threshold-label"><strong>{{ metric('temperature').label }}</strong><span>正常范围 / {{ metric('temperature').unit }}</span></div><label>最低值<el-input-number v-model="form.temperature.min" :precision="1" :step="0.1" controls-position="right" /></label><label>最高值<el-input-number v-model="form.temperature.max" :precision="1" :step="0.1" controls-position="right" /></label></div><div class="threshold-row"><div class="threshold-label"><strong>{{ metric('ph').label }}</strong><span>正常范围</span></div><label>最低值<el-input-number v-model="form.ph.min" :precision="1" :step="0.1" controls-position="right" /></label><label>最高值<el-input-number v-model="form.ph.max" :precision="1" :step="0.1" controls-position="right" /></label></div><div class="threshold-row do-row"><div class="threshold-label"><strong>溶解氧 DO</strong><span>分级预警与自动控制 / mg/L</span></div><label>黄色预警<el-input-number v-model="form.dissolvedOxygen.yellow" :precision="1" :step="0.1" controls-position="right" /></label><label>橙色预警<el-input-number v-model="form.dissolvedOxygen.orange" :precision="1" :step="0.1" controls-position="right" /></label><label>红色预警<el-input-number v-model="form.dissolvedOxygen.red" :precision="1" :step="0.1" controls-position="right" /></label><label>自动启动<el-input-number v-model="form.dissolvedOxygen.aeratorOn" :precision="1" :step="0.1" controls-position="right" /></label><label>自动停止<el-input-number v-model="form.dissolvedOxygen.aeratorOff" :precision="1" :step="0.1" controls-position="right" /></label></div><div class="threshold-row"><div class="threshold-label"><strong>氨氮</strong><span>预警阈值 / mg/L</span></div><label>预警值<el-input-number v-model="form.ammoniaNitrogen.warning" :precision="2" :step="0.01" controls-position="right" /></label></div><div class="threshold-row"><div class="threshold-label"><strong>盐度</strong><span>正常范围 / ‰</span></div><label>最低值<el-input-number v-model="form.salinity.min" :precision="1" :step="0.1" controls-position="right" /></label><label>最高值<el-input-number v-model="form.salinity.max" :precision="1" :step="0.1" controls-position="right" /></label></div><div class="threshold-row"><div class="threshold-label"><strong>亚硝酸盐</strong><span>预警阈值 / mg/L</span></div><label>预警值<el-input-number v-model="form.nitrite.warning" :precision="2" :step="0.01" controls-position="right" /></label></div></div></section></div><aside class="settings-side"><section class="panel culture-panel"><div class="panel-heading"><div><span class="section-kicker">CULTURE PROFILE</span><h2>养殖配置</h2></div></div><div class="settings-field"><label>养殖品种</label><el-select v-model="cultureForm.species"><el-option v-for="species in CULTURE_OPTIONS.species" :key="species" :label="species" :value="species" /></el-select></div><div class="settings-field"><label>生长阶段</label><el-select v-model="cultureForm.stage"><el-option v-for="stage in CULTURE_OPTIONS.stages" :key="stage" :label="stage" :value="stage" /></el-select></div><div class="culture-note"><el-icon><Connection /></el-icon><span>后续可根据品种和生长阶段自动切换阈值模板。</span></div></section><section class="panel settings-future"><span class="section-kicker">PLANNED CONFIGURATION</span><h2>后续配置预留</h2><p>自动控制规则模板</p><p>设备分组与权限</p><p>传感器校准参数</p></section></aside></section></PageShell>
</template>
